{
  "name": "opencode-orchestrator-kit",
  "version": "1.1.1",
  "description": "OpenCode plugin that routes coding work across specialist agents. Registers the orchestrator workflow, plan-board tooling, session-memory rules, kit skills, and the /start-session, /recall, /research-mode, and /close-session commands.",
  "homepage": "https://nicogenti.github.io/opencode-orchestrator-kit/",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-agents",
    "ai-agents",
    "multi-agent",
    "orchestrator",
    "coding-agent",
    "llm",
    "developer-tools"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/NicoGenti/opencode-orchestrator-kit.git",
    "directory": "plugin"
  },
  "type": "module",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "types",
    "assets"
  ],
  "peerDependencies": {
    "@opencode/plugin": "^2.1.0"
  },
  "scripts": {
    "prepack": "bun ../scripts/sync-assets.ts"
  }
}
